// Weighted picker driven by real Instagram analytics (n8n/workflows/distribution-daily-report.json
// runs the daily job that computes these weights from Reels engagement). Round-robin state lives
// in this workflow's static data so it survives across scheduled firings indefinitely -- unlike
// the per-execution research-cycle guard in the topic workers, this must NOT reset per execution.
// It is also the fallback path whenever fresh weights aren't available for every arm yet (renderer
// unreachable, or the very first days before enough posts exist to weigh), so early/degraded runs
// stay evenly distributed instead of getting stuck on stale or partial data.
const roster = [{"workflowId": "aMAQt4XFc3dQoJ18", "workflowName": "Agentic AI & Coding Agents: Tips Reel", "slug": "agentic-ai", "format": "tips"}, {"workflowId": "544pSlOJiOpgWcdu", "workflowName": "Agentic AI & Coding Agents: Trend Reel", "slug": "agentic-ai", "format": "trend"}, {"workflowId": "31QYT1GhUh6qji9f", "workflowName": "Editor & IDE Power Features: Tips Reel", "slug": "editor-ide", "format": "tips"}, {"workflowId": "8BDCLy1n57fBtArF", "workflowName": "Editor & IDE Power Features: Trend Reel", "slug": "editor-ide", "format": "trend"}, {"workflowId": "oabUY0nYfgqfVPOw", "workflowName": "Git & CLI Tricks: Tips Reel", "slug": "git-cli", "format": "tips"}, {"workflowId": "cON3J0BYweklJx9Y", "workflowName": "Git & CLI Tricks: Trend Reel", "slug": "git-cli", "format": "trend"}, {"workflowId": "8qJ45bzEhYJcPMcX", "workflowName": "Debugging & Observability: Tips Reel", "slug": "debugging-observability", "format": "tips"}, {"workflowId": "WERLRUMuwApEAxOL", "workflowName": "Debugging & Observability: Trend Reel", "slug": "debugging-observability", "format": "trend"}, {"workflowId": "e0TxVmd9Oo92bwRJ", "workflowName": "Databases & Performance: Tips Reel", "slug": "databases-performance", "format": "tips"}, {"workflowId": "L7kYirg3MkRT4iVi", "workflowName": "Databases & Performance: Trend Reel", "slug": "databases-performance", "format": "trend"}];
const staticData = $getWorkflowStaticData('global');

function roundRobinFallback() {
  const currentIndex = Number(staticData.nextTopicIndex ?? 0) % roster.length;
  staticData.nextTopicIndex = (currentIndex + 1) % roster.length;
  return {...roster[currentIndex], weight: null, rotationIndex: currentIndex, selectionMode: 'round-robin'};
}

const fetchedWeights = Array.isArray($json?.weights) ? $json.weights : [];
const weightByKey = new Map(fetchedWeights.map((entry) => [`${entry.slug}:${entry.format}`, Number(entry.weight)]));
const everyArmWeighted = roster.every((entry) => weightByKey.has(`${entry.slug}:${entry.format}`));

let selected = null;
if (everyArmWeighted) {
  const weighted = roster.map((entry) => ({...entry, weight: weightByKey.get(`${entry.slug}:${entry.format}`)}));
  const totalWeight = weighted.reduce((sum, entry) => sum + Math.max(entry.weight, 0), 0);
  if (totalWeight > 0) {
    let roll = Math.random() * totalWeight;
    const picked = weighted.find((entry) => { roll -= Math.max(entry.weight, 0); return roll <= 0; }) ?? weighted[weighted.length - 1];
    selected = {...picked, rotationIndex: null, selectionMode: 'weighted'};
  }
}
if (!selected) selected = roundRobinFallback();

return [{json: {workflowId: selected.workflowId, workflowName: selected.workflowName, topicSlug: selected.slug, format: selected.format, weight: selected.weight ?? null, rotationIndex: selected.rotationIndex, rosterSize: roster.length, selectionMode: selected.selectionMode}}];
